function Sparkline({ series, color = 'hsl(var(--primary))' }: { series?: { value: number }[]; color?: string }) {
  const values = series?.length ? series.map((p) => p.value) : [22, 29, 26, 39, 35, 46, 44, 57];
  const max = Math.max(...values), min = Math.min(...values);
  const points = values.map((v, i) => `${(i / Math.max(1, values.length - 1)) * 100},${42 - ((v - min) / Math.max(1, max - min)) * 34}`).join(' ');
  return <svg viewBox="0 0 100 46" preserveAspectRatio="none" className="h-12 w-full overflow-visible"><polyline points={points} fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" /></svg>;
}

function Metric({ label, value, change, tone = 'teal', icon: Icon }: { label: string; value: string; change?: number; tone?: 'teal' | 'lime' | 'amber' | 'coral'; icon: typeof TrendingUp }) {
  const tones = { teal: 'bg-secondary text-primary', lime: 'bg-[#eff3c6] text-[#596000]', amber: 'bg-[#fff0d9] text-[#a76619]', coral: 'bg-[#fbe5df] text-destructive' };
  return <div className="surface rounded-2xl p-5 animate-rise animate-rise-1"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mono mt-2 text-[25px] font-bold tracking-[-.08em]">{value}</p></div><div className={`grid h-9 w-9 place-items-center rounded-xl ${tones[tone]}`}><Icon size={17} /></div></div>{change !== undefined && <div className={`mt-4 flex items-center gap-1 text-[11px] font-bold ${change >= 0 ? 'text-primary' : 'text-destructive'}`}>{change >= 0 ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{Math.abs(change).toFixed(1)}% <span className="font-medium text-muted-foreground">vs last period</span></div>}</div>;
}

function SectionTitle({ children, action }: { children: ReactNode; action?: ReactNode }) {
  return <div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-bold tracking-[-.02em]">{children}</h2>{action}</div>;
}

